// HandlePreInvocation parses the raw JSON payload and handles PreInvocation hook events.
// By contract, it returns "{}" on normal completion, empty payload, malformed JSON, or error (fail-open).
func HandlePreInvocation(ctx context.Context, rawPayload []byte, opts ...HookOption) ([]byte, error) {
	if ctx == nil {
		ctx = context.Background()
	}

	defer func() {
		if r := recover(); r != nil {
			fmt.Fprintf(os.Stderr, "[repo-memory] PreInvocation panic recovered: %v\n", r)
		}
	}()

	defaultResp := []byte("{}")
	if len(rawPayload) == 0 || strings.TrimSpace(string(rawPayload)) == "" {
		return defaultResp, nil
	}

	var payload PreInvocationPayload
	if err := json.Unmarshal(rawPayload, &payload); err != nil {
		fmt.Fprintf(os.Stderr, "[repo-memory] PreInvocation malformed JSON: %v (failing open)\n", err)
		return defaultResp, nil
	}
	payload.Normalize()

	return defaultResp, nil
}

