func TestPreToolUse_Contracts(t *testing.T) {
	tests := []struct {
		name      string
		payload   []byte
		wantErr   bool
		wantAllow bool
	}{
		{
			name:      "valid tool use payload",
			payload:   []byte(`{"conversationId":"c1","toolName":"run_command","toolInput":{"command":"ls"}}`),
			wantErr:   false,
			wantAllow: true,
		},
		{
			name:      "empty stdout/input (fail open)",
			payload:   []byte(""),
			wantErr:   false,
			wantAllow: true,
		},
		{
			name:      "whitespace stdout/input (fail open)",
			payload:   []byte("   \n\t  "),
			wantErr:   false,
			wantAllow: true,
		},
		{
			name:      "empty object {} (fail open, MUST be allow, not deny)",
			payload:   []byte("{}"),
			wantErr:   false,
			wantAllow: true,
		},
		{
			name:      "malformed JSON (fail open)",
			payload:   []byte("{malformed: true,"),
			wantErr:   false,
			wantAllow: true,
		},
		{
			name:      "non-JSON raw string (fail open)",
			payload:   []byte("not json at all"),
			wantErr:   false,
			wantAllow: true,
		},
		{
			name:      "nil payload (fail open)",
			payload:   nil,
			wantErr:   false,
			wantAllow: true,
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			out, err := HandlePreToolUse(context.Background(), tc.payload)
			if (err != nil) != tc.wantErr {
				t.Fatalf("HandlePreToolUse() error = %v, wantErr %v", err, tc.wantErr)
			}
			if tc.wantAllow {
				var parsed struct {
					Decision string `json:"decision"`
				}
				if err := json.Unmarshal(out, &parsed); err != nil {
					t.Fatalf("failed to parse output JSON %q: %v", string(out), err)
				}
				if parsed.Decision != "allow" {
					t.Errorf("expected decision 'allow', got %q in %s", parsed.Decision, string(out))
				}
			}
		})
	}
}

