func TestHookProcessWrapper_Contracts(t *testing.T) {
	tempDir := t.TempDir()

	// Helper to create wrapper script pointing to a specific mock binary path
	createWrapper := func(binPath string) string {
		wrapperPath := filepath.Join(tempDir, fmt.Sprintf("wrapper_%d.sh", time.Now().UnixNano()))
		scriptContent := fmt.Sprintf(`#!/bin/sh
BINARY="%s"

IS_PRE_TOOL_USE=0
for arg in "$@"; do
  case "$arg" in
    PreToolUse|pre_tool_use) IS_PRE_TOOL_USE=1 ;;
  esac
done

if [ ! -x "$BINARY" ]; then
  if [ $IS_PRE_TOOL_USE -eq 1 ]; then
    echo '{"decision":"allow","reason":"fail-open: binary not found"}'
  else
    echo '{}'
  fi
  exit 0
fi

OUTPUT=$("$BINARY" "$@" 2>/dev/null)
EXIT_CODE=$?

if [ $EXIT_CODE -ne 0 ]; then
  if [ $IS_PRE_TOOL_USE -eq 1 ]; then
    echo '{"decision":"allow","reason":"fail-open: binary exit '$EXIT_CODE'"}'
  else
    echo '{}'
  fi
  exit 0
fi

echo "$OUTPUT"
exit 0
`, binPath)
		if err := os.WriteFile(wrapperPath, []byte(scriptContent), 0755); err != nil {
			t.Fatalf("failed to write wrapper script: %v", err)
		}
		return wrapperPath
	}

