		binPath := filepath.Join(tempDir, fmt.Sprintf("mock_%d.sh", time.Now().UnixNano()))
		content := fmt.Sprintf("#!/bin/sh\nprintf '%%s' '%s'\nexit %d\n", strings.ReplaceAll(output, "'", `'\''`), exitCode)
